"""Validate only metadata, then feed the actual compiled Java child with real FDs."""
import json,os,pathlib,signal,subprocess,sys
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parent))
from format_io import normalize
HERE=pathlib.Path(__file__).resolve().parent
if os.geteuid()==0:raise SystemExit('Run as an ordinary nonroot user.')
try:data=normalize(sys.stdin.buffer.read(32*1024**2+1))
except (ValueError,TypeError,KeyError,UnicodeError,RecursionError,OverflowError):
    print('{"error":"INPUT"}');raise SystemExit(0)
proc=None
signals={signal.SIGINT,signal.SIGTERM}
def interrupted(sig,frame):
    for s in signals:signal.signal(s,signal.SIG_IGN)
    raise KeyboardInterrupt()
for s in signals:signal.signal(s,interrupted)
try:
    signal.pthread_sigmask(signal.SIG_BLOCK,signals)
    try:
        proc=subprocess.Popen([sys.executable,'-I','-B',str(HERE/'launch.py'),sys.argv[1] if len(sys.argv)>1 else '/workspace/tmp/classes'],stdin=subprocess.PIPE,close_fds=True,
            env={'PATH':'/opt/java/bin:/usr/local/bin:/usr/bin:/bin','HOME':'/workspace','LANG':'C','LC_ALL':'C','TMPDIR':'/workspace/tmp','PYTHONUNBUFFERED':'1','PYTHONDONTWRITEBYTECODE':'1','PYTHONHASHSEED':'0','OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1'})
    finally:signal.pthread_sigmask(signal.SIG_UNBLOCK,signals)
    proc.communicate(data)
    status=proc.returncode
except KeyboardInterrupt:status=130
finally:
    for s in signals:signal.signal(s,signal.SIG_IGN)
    if proc is not None:
        if proc.poll() is None:proc.kill()
        proc.wait(timeout=5)
raise SystemExit(status)

"""Validate external metadata only; raw packet/frame bytes stay opaque."""
import json,re
MAX=2**62-1
HEX=re.compile(r'(?:[0-9a-fA-F]{2})*\Z',re.ASCII)
def pairs(items):
    out={}
    for k,v in items:
        if k in out:raise ValueError('duplicate decoded key')
        out[k]=v
    return out
def num(x,limit=MAX):return type(x) is int and 0<=x<=limit
def shape(x,names):return type(x) is dict and x.keys()==set(names.split())
def hex_bytes(x,low=0,high=8*1024**2):
    if type(x) is not str or not HEX.fullmatch(x) or not low<=len(x)//2<=high:raise ValueError('hex')
    return bytes.fromhex(x)
def normalize(raw):
    if len(raw)>32*1024**2:raise ValueError('stdin cap')
    def bad(x):raise ValueError('noninteger/nonfinite')
    batch=json.loads(raw.decode('utf-8'),object_pairs_hook=pairs,parse_float=bad,parse_constant=bad)
    if not shape(batch,'traces') or type(batch['traces']) is not list or len(batch['traces'])>64:raise ValueError('batch')
    events=wire_bytes=local_ids=0;lines=[str(len(batch['traces']))]
    for t in batch['traces']:
        if not shape(t,'limits local peer received events'):raise ValueError('trace')
        a,b,c,d=t['limits'],t['local'],t['peer'],t['received']
        if not shape(a,'connection stream bidi uni cids') or not shape(b,'bidi uni cids') or not shape(c,'cid token') or not shape(d,'I H A'):raise ValueError('configuration')
        if not all(num(a[k]) for k in ['connection','stream']) or not all(num(x[k],2**60) for x in [a,b] for k in ['bidi','uni']):raise ValueError('limits')
        if not num(a['cids'],4096) or a['cids']<2:raise ValueError('CID limit')
        ids=b['cids']
        if type(ids) is not list or not 1<=len(ids)<=4096:raise ValueError('local CIDs')
        decoded=[hex_bytes(x,1,20) for x in ids]
        if len(set(decoded))!=len(decoded) or len({len(x) for x in decoded})!=1:raise ValueError('CID uniqueness/width')
        local_ids+=len(ids);peer=hex_bytes(c['cid'],1,20);token=hex_bytes(c['token'],16,16)
        if any(x is not None and not num(x) for x in d.values()):raise ValueError('received seed')
        if type(t['events']) is not list:raise ValueError('events')
        lines.append(' '.join(str(x) for x in [a['connection'],a['stream'],a['bidi'],a['uni'],a['cids'],b['bidi'],b['uni']]))
        lines.append(' '.join(x.hex() for x in decoded));lines.append(peer.hex()+' '+token.hex())
        lines.append(' '.join('-' if d[k] is None else str(d[k]) for k in ['I','H','A']))
        lines.append(str(len(t['events'])));events+=len(t['events'])
        for e in t['events']:
            if shape(e,'keys'):
                keys=e['keys']
                if type(keys) is not list or len(keys)>3 or any(type(k) is not str or k not in ['I','H','A'] for k in keys) or len(set(keys))!=len(keys):raise ValueError('keys')
                lines.append('K'+''.join(' '+k for k in keys))
            elif shape(e,'datagram'):
                dg=e['datagram']
                if not shape(dg,'wire auth') or type(dg['auth']) is not list or len(dg['auth'])>256:raise ValueError('datagram metadata')
                if any(x is not None and not num(x) for x in dg['auth']):raise ValueError('authentication annotation')
                wire=hex_bytes(dg['wire']);wire_bytes+=len(wire)
                lines.append('D '+(dg['wire'] or '-'))
                lines.append(' '.join('-' if x is None else str(x) for x in dg['auth']) or '-')
            else:raise ValueError('event')
    if events>8192 or wire_bytes>8*1024**2 or local_ids>16384:raise ValueError('structural caps')
    return ('\n'.join(lines)+'\n').encode('ascii')

#!/usr/bin/env python3
"""Compile sources, then run bounded real children on public sanity fixtures."""
import json, os, pathlib, sys, tempfile
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parent))
from capture import child
from format_io import pairs
HERE=pathlib.Path(__file__).resolve().parent

def strict_json(raw):
    def bad(x):raise ValueError('noninteger/nonfinite JSON output')
    return json.loads(raw.decode('utf-8'),object_pairs_hook=pairs,parse_constant=bad,parse_float=bad)

def equivalent(a,b):
    if type(a) is not type(b):return False
    if isinstance(a,dict):return a.keys()==b.keys() and all(equivalent(a[k],b[k]) for k in a)
    if isinstance(a,list):return len(a)==len(b) and all(equivalent(x,y) for x,y in zip(a,b))
    return a==b

def main():
    if os.geteuid()==0:raise ValueError('Run public checks as an ordinary nonroot user.')
    source=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else HERE/'submission/src').resolve()
    scratch=pathlib.Path('/workspace/tmp');scratch.mkdir(exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='public-codec-',dir=scratch) as tmp:
        classes=pathlib.Path(tmp)/'classes'
        code,out,err=child([sys.executable,'-I','-B',str(HERE/'build.py'),str(source),str(classes)],timeout=180)
        if code:raise ValueError('Compilation failed: '+err.decode('utf-8','replace')[:4000]+out.decode('utf-8','replace')[:1000])
        fixtures=strict_json((HERE/'examples.json').read_bytes())
        for case in fixtures:
            code,out,err=child([sys.executable,'-I','-B',str(HERE/'run.py'),str(classes)],case['stdin'].encode('utf-8'),timeout=180)
            if code:raise ValueError('Candidate nonzero exit on '+case['name']+': '+str(code)+' '+err.decode('utf-8','replace')[:1000])
            if not equivalent(strict_json(out),case['expected']):raise ValueError('Public fixture failed: '+case['name'])
    print('Public checks passed ('+str(len(fixtures))+' fixtures).')

if __name__=='__main__':
    try:main()
    except (Exception,KeyboardInterrupt) as error:
        print(str(error),file=sys.stderr);raise SystemExit(1)

