def v(value,width=None):
    if width is None:width=next(w for w in [1,2,4,8] if value<2**(8*w-2))
    if width not in [1,2,4,8] or not 0<=value<2**(8*width-2):raise ValueError('varint')
    return (([1,2,4,8].index(width)<<(8*width-2))|value).to_bytes(width,'big')
def envelope(level,pn,body,cid=b'\xaa',scid=b'\xbb',token=b'',width=1,phase=0,spin=0,length_width=None):
    number=(pn%(2**(8*width))).to_bytes(width,'big')
    if level=='A':return bytes([0x40|(spin<<5)|(phase<<2)|(width-1)])+cid+number+body
    head=bytes([(0xc0 if level=='I' else 0xe0)|(width-1)])+b'\0\0\0\1'+bytes([len(cid)])+cid+bytes([len(scid)])+scid
    if level=='I':head+=v(len(token))+token
    return head+v(width+len(body),length_width)+number+body
