public final class ReceiveAudit {

    static final long MAXP = (1L << 62) - 1;
    static final long MAXSTREAMS = 1L << 60;
    private static final String FE = "FRAME_ENCODING_ERROR";
    private static final String PV = "PROTOCOL_VIOLATION";

    /** Frame decode/semantic failure; offset assigned by the frame loop. */
    private static final class Fail extends Exception {
