            super(code);
            this.code = code;
            this.offset = offset;
        }
    }

    private static final class EpochRec {
        long min, max, count;

        EpochRec(long v) {
            min = max = v;
            count = 1;
        }
    }

    private static final class CidRec {
        final byte[] cid, token;

