    /** Minimal varint / raw output buffer. */
    private static final class Out {
        final ByteArrayOutputStream buf = new ByteArrayOutputStream();

        void u8(int b) {
            buf.write(b);
        }

        void raw(byte[] b) {
            buf.write(b, 0, b.length);
        }

        void v(long val) {
            raw(venc(val));
        }
    }

    static byte[] venc(long val) {
        if (val < 0) throw new IllegalArgumentException();
        if (val < 64) return new byte[] {(byte) val};
        if (val < 16384) return new byte[] {(byte) (0x40 | (val >> 8)), (byte) val};
        if (val < (1L << 30)) {
            return new byte[] {
                (byte) (0x80 | (val >> 24)), (byte) (val >> 16), (byte) (val >> 8), (byte) val
            };
        }
        return new byte[] {
            (byte) (0xc0 | (val >> 56)),
            (byte) (val >> 48),
            (byte) (val >> 40),
            (byte) (val >> 32),
            (byte) (val >> 24),
            (byte) (val >> 16),
            (byte) (val >> 8),
            (byte) val
        };
    }

    // ------------------------------------------------------------------ journal
    private final ArrayDeque<Runnable> undo = new ArrayDeque<>();

    private void push(Runnable r) {
        undo.push(r);
    }

    private void rollback() {
        while (!undo.isEmpty()) undo.pop().run();
    }

    private void commitPacket() {
        undo.clear();
    }

    @SuppressWarnings("unchecked")
    private <K, V> void jput(Map<K, V> m, K k, V v) {
        V old = m.put(k, v);
        Map<K, Object> mm = (Map<K, Object>) m;
        push(() -> {
            if (old == null) mm.remove(k);
            else mm.put(k, old);
        });
    }

    @SuppressWarnings("unchecked")
    private <K> void jremove(Map<K, ?> m, K k) {
        Object old = m.remove(k);
        Map<K, Object> mm = (Map<K, Object>) m;
        push(() -> mm.put(k, old));
    }

    private void jadd(TreeSet<Long> s, long v) {
        if (s.add(v)) push(() -> s.remove(v));
    }

    private void jdel(TreeSet<Long> s, long v) {
        if (s.remove(v)) push(() -> s.add(v));
    }

    // ------------------------------------------------------------------ state
    private long limConn, limStream, limBidi, limUni, localBidi, localUni;
    private int limCids;
    private List<byte[]> localCids;
    private byte[] peerCid, peerToken;

    private boolean closed;
    private int closeEvent, closePacket, closeOffset;
    private String closeCode;

    private final boolean[] keys = {true, false, false};
    private final Long[] largest = new Long[3];
    private final List<Set<Long>> seen = new ArrayList<>();
    private final List<AckState> acks = new ArrayList<>();
    private final List<TreeMap<Long, byte[]>> crypto = new ArrayList<>();
    private final TreeMap<Long, StreamState> streams = new TreeMap<>();
    private long used, openBidi, openUni, sendMaxData, sendMaxStreamsBidi, sendMaxStreamsUni;
    private final TreeMap<Long, EpochRec> epochs = new TreeMap<>();
    private long currentEpoch;
    private final TreeMap<Long, CidRec> peerObserved = new TreeMap<>();
    private final Map<String, Long> cidOwner = new HashMap<>();
    private final TreeSet<Long> peerActive = new TreeSet<>();
    private long retirePriorTo;
    private final TreeSet<Long> retiredLocal = new TreeSet<>();

    private final List<Object> outPackets = new ArrayList<>();
    private final List<Object> outDatagrams = new ArrayList<>();

    private String curStatus, curHash;

    // ------------------------------------------------------------------ helpers
    private static MessageDigest digest() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static String hex(byte[] b) {
        return Main.hex(b);
    }

    private static String sha256hex(byte[] data) {
        return hex(digest().digest(data));
    }

    private static byte[] lowBytes(long pn, int w) {
        byte[] out = new byte[w];
        for (int i = 0; i < w; i++) out[w - 1 - i] = (byte) (pn >> (8 * i));
        return out;
    }

    /** PN reconstruction: nonnegative value congruent to raw mod 2^(8*width) closest to expected,
     * ties choose the larger value. */
    static long decodePn(long raw, long width, long expected) {
        long w = 1L << (8 * width);
        long d = expected - raw;
        if (d <= 0) return raw;
        long k = d / w;
        long r = d % w;
        if (2 * r >= w) k++;
        return raw + k * w;
    }

    static int canonWidth(long pn, long expected) {
        for (int w = 1; w <= 4; w++) {
            long mask = (1L << (8 * w)) - 1;
            if (decodePn(pn & mask, w, expected) == pn) return w;
        }
        return 4;
    }

