    // ------------------------------------------------------------------ headers
    private static long headerVarint(byte[] w, int[] p) {
        if (p[0] >= w.length) return -1;
        int b = w[p[0]] & 0xff;
        int len = 1 << (b >>> 6);
        if (p[0] + len > w.length) return -1;
        long v = b & 0x3f;
        for (int i = 1; i < len; i++) v = (v << 8) | (w[p[0] + i] & 0xff);
        p[0] += len;
        return v;
    }

    private Env parseHeader(byte[] w, int off) {
        Env e = new Env();
        e.off = off;
        int b0 = w[off] & 0xff;
        int[] p = new int[] {off + 1};
        if ((b0 & 0x80) != 0) {
            int kind = b0 & 0xfc;
            if (kind == 0xc0) e.level = 0;
            else if (kind == 0xe0) e.level = 1;
            else return null;
            e.pnWidth = (b0 & 3) + 1;
            if (p[0] + 4 > w.length) return null;
            if ((w[p[0]] & 255) != 0 || (w[p[0] + 1] & 255) != 0 || (w[p[0] + 2] & 255) != 0
                    || (w[p[0] + 3] & 255) != 1) return null;
            p[0] += 4;
            if (p[0] >= w.length) return null;
            int dl = w[p[0]++] & 255;
            if (dl > 20 || p[0] + dl > w.length) return null;
            e.dcid = Arrays.copyOfRange(w, p[0], p[0] + dl);
            p[0] += dl;
            if (p[0] >= w.length) return null;
            int sl = w[p[0]++] & 255;
            if (sl > 20 || p[0] + sl > w.length) return null;
            e.scid = Arrays.copyOfRange(w, p[0], p[0] + sl);
            p[0] += sl;
            if (e.level == 0) {
                long tl = headerVarint(w, p);
                if (tl < 0 || tl > w.length - p[0]) return null;
                e.token = Arrays.copyOfRange(w, p[0], p[0] + (int) tl);
                p[0] += (int) tl;
            } else {
                e.token = new byte[0];
            }
            long len = headerVarint(w, p);
            if (len < 0 || len < e.pnWidth || len > w.length - p[0]) return null;
            long pnRaw = 0;
            for (int i = 0; i < e.pnWidth; i++) pnRaw = (pnRaw << 8) | (w[p[0] + i] & 255);
            e.pnRaw = pnRaw;
            p[0] += e.pnWidth;
            e.payload = Arrays.copyOfRange(w, p[0], p[0] + (int) (len - e.pnWidth));
            return e;
        } else {
            if ((b0 & 0x40) == 0) return null;
            if ((b0 & 0x18) != 0) return null;
            e.level = 2;
            e.phase = (b0 >> 2) & 1;
            e.pnWidth = (b0 & 3) + 1;
            int cw = localCids.get(0).length;
            if (p[0] + cw + e.pnWidth > w.length) return null;
            e.dcid = Arrays.copyOfRange(w, p[0], p[0] + cw);
            p[0] += cw;
            long pnRaw = 0;
            for (int i = 0; i < e.pnWidth; i++) pnRaw = (pnRaw << 8) | (w[p[0] + i] & 255);
            e.pnRaw = pnRaw;
            p[0] += e.pnWidth;
            e.scid = new byte[0];
            e.token = new byte[0];
            e.payload = Arrays.copyOfRange(w, p[0], w.length);
            return e;
        }
    }

