    private void processDatagram(int ev, byte[] wire, List<Long> auth) {
        int off = 0;
        int pkt = 0;
        ByteArrayOutputStream acceptedOut = new ByteArrayOutputStream();
        int accepted = 0;
        while (off < wire.length) {
            Env env = parseHeader(wire, off);
            if (env == null) {
