    /** Bytes consumed by this envelope inside its datagram (header + pn + payload). */
    private static int headerSize(Env e) {
        // recompute from payload + pn width + known header overhead
        return e.consumed;
    }

    // ------------------------------------------------------------------ envelope
    private void processEnvelope(int ev, int pkt, Env env, Long ann, ByteArrayOutputStream acceptedOut) {
        int level = env.level;
        long expected = largest[level] != null ? largest[level] + 1 : 0;
        long pn = decodePn(env.pnRaw, env.pnWidth, expected);
        Long epochOut = null;
        String status;
        String hash = null;
        if (closed) {
            status = "CLOSED";
        } else if (!routeOk(env)) {
            status = "DROP_CID";
        } else if (!keys[level]) {
            status = "NO_KEY";
        } else if (pn > MAXP) {
            status = "PN_RANGE";
        } else {
            boolean authOk;
            Long g = null;
            if (level == 2) {
                g = ann;
                authOk =
                        ann != null
                                && (ann == currentEpoch - 1 || ann == currentEpoch
                                        || ann == currentEpoch + 1)
                                && ((ann & 1) == env.phase);
            } else {
                authOk = !auth.isEmpty() && auth.get(0) != null;
            }
            if (!authOk) {
                status = "AUTH";
            } else {
                if (level == 2) epochOut = g;
                if (seen.get(level).contains(pn)) {
                    status = "DUPLICATE";
                } else if (level == 2 && epochViolation(g, pn)) {
                    status = "KEY_UPDATE_ERROR";
                    close(ev, pkt, 0, "KEY_UPDATE_ERROR");
                } else {
                    if (level == 2) applyEpoch(g, pn);
                    curStatus = null;
                    curHash = null;
                    frameAudit(ev, pkt, env, level, pn, expected, acceptedOut);
                    status = curStatus;
                    hash = curHash;
                }
            }
        }
        outPackets.add(
                Main.object(
                        "event",
                        (long) ev,
                        "packet",
                        (long) pkt,
                        "offset",
                        (long) env.off,
                        "level",
                        level == 0 ? "I" : level == 1 ? "H" : "A",
                        "pn",
                        pn,
                        "epoch",
                        epochOut,
                        "status",
                        status,
                        "sha256",
                        hash));
    }

    private boolean routeOk(Env env) {
        for (int i = 0; i < localCids.size(); i++) {
            if (Arrays.equals(localCids.get(i), env.dcid)) {
                env.destSeq = i;
                return !retiredLocal.contains((long) i);
            }
        }
        return false;
    }

    private void close(int ev, int pkt, int offset, String code) {
