    private boolean epochViolation(long g, long pn) {
        for (Map.Entry<Long, EpochRec> e : epochs.entrySet()) {
            long h = e.getKey();
            if (h < g && pn <= e.getValue().max) return true;
            if (h > g && pn >= e.getValue().min) return true;
        }
        return false;
    }

    private void applyEpoch(long g, long pn) {
        EpochRec rec = epochs.get(g);
        if (rec == null) {
            EpochRec nr = new EpochRec(pn);
            jput(epochs, g, nr);
        } else {
            EpochRec nr = new EpochRec(0);
            nr.min = Math.min(rec.min, pn);
            nr.max = Math.max(rec.max, pn);
            nr.count = rec.count + 1;
            jput(epochs, g, nr);
        }
        if (g == currentEpoch + 1) {
            long old = currentEpoch;
            push(() -> currentEpoch = old);
            currentEpoch = g;
        }
    }

    // ------------------------------------------------------------------ frames
    private void frameAudit(
            int ev,
            int pkt,
            Env env,
            int level,
            long pn,
            long expected,
            ByteArrayOutputStream acceptedOut) {
        byte[] pl = env.payload;
        List<byte[]> canon = new ArrayList<>();
        int[] p = new int[1];
        try {
            if (pl.length == 0) throw new CloseFail(FE, 0);
            while (p[0] < pl.length) {
                int frameStart = p[0];
                Out o = new Out();
                boolean isClose;
                try {
                    isClose = decodeFrame(pl, p, level, env.destSeq, o);
                } catch (Fail f) {
                    throw new CloseFail(f.code, frameStart);
                }
                canon.add(o.buf.toByteArray());
                if (isClose) {
                    commitPacket();
                    accept(level, pn);
                    byte[] wire = canonicalEnvelope(env, pn, expected, concat(canon));
                    acceptedOut.write(wire, 0, wire.length);
                    curHash = sha256hex(wire);
                    curStatus = "PEER_CLOSE";
                    close(ev, pkt, frameStart, "PEER_CLOSE");
                    return;
                }
            }
            commitPacket();
            accept(level, pn);
            byte[] wire = canonicalEnvelope(env, pn, expected, concat(canon));
            acceptedOut.write(wire, 0, wire.length);
            curHash = sha256hex(wire);
            curStatus = "OK";
        } catch (CloseFail cf) {
            rollback();
            close(ev, pkt, cf.offset, cf.code);
            curStatus = cf.code;
            curHash = null;
        }
    }

    private void accept(int level, long pn) {
        seen.get(level).add(pn);
        if (largest[level] == null || pn > largest[level]) largest[level] = pn;
    }

    private static byte[] concat(List<byte[]> parts) {
        int n = 0;
        for (byte[] b : parts) n += b.length;
        byte[] out = new byte[n];
        int o = 0;
        for (byte[] b : parts) {
            System.arraycopy(b, 0, out, o, b.length);
            o += b.length;
        }
        return out;
    }

    private byte[] canonicalEnvelope(Env env, long pn, long expected, byte[] payload) {
        int w = canonWidth(pn, expected);
        byte[] pnBytes = lowBytes(pn, w);
        Out o = new Out();
        if (env.level == 2) {
            o.u8(0x40 | (env.phase << 2) | (w - 1));
            o.raw(env.dcid);
        } else {
            o.u8((env.level == 0 ? 0xc0 : 0xe0) | (w - 1));
            o.raw(new byte[] {0, 0, 0, 1});
            o.u8(env.dcid.length);
            o.raw(env.dcid);
            o.u8(env.scid.length);
            o.raw(env.scid);
            if (env.level == 0) {
                o.v(env.token.length);
                o.raw(env.token);
            }
            o.v((long) w + payload.length);
        }
        o.raw(pnBytes);
        o.raw(payload);
        return o.buf.toByteArray();
    }

    private long varint(byte[] a, int[] p) throws Fail {
        if (p[0] >= a.length) throw new Fail(FE);
        int b = a[p[0]] & 0xff;
        int len = 1 << (b >>> 6);
        if (p[0] + len > a.length) throw new Fail(FE);
        long v = b & 0x3f;
        for (int i = 1; i < len; i++) v = (v << 8) | (a[p[0] + i] & 0xff);
        p[0] += len;
        return v;
    }

    private long readType(byte[] a, int[] p) throws Fail {
        if (p[0] >= a.length) throw new Fail(FE);
        int b = a[p[0]] & 0xff;
        int len = 1 << (b >>> 6);
        if (p[0] + len > a.length) throw new Fail(FE);
        long v = b & 0x3f;
        for (int i = 1; i < len; i++) v = (v << 8) | (a[p[0] + i] & 0xff);
        p[0] += len;
        if (len == 2 && v < 64) throw new Fail(FE);
        if (len == 4 && v < 16384) throw new Fail(FE);
        if (len == 8 && v < (1L << 30)) throw new Fail(FE);
        return v;
    }

    private int u8(byte[] a, int[] p) throws Fail {
        if (p[0] >= a.length) throw new Fail(FE);
        return a[p[0]++] & 0xff;
    }

    private byte[] take(byte[] a, int[] p, long n) throws Fail {
        if (n < 0 || n > a.length - p[0]) throw new Fail(FE);
        byte[] out = Arrays.copyOfRange(a, p[0], p[0] + (int) n);
        p[0] += (int) n;
        return out;
    }

    private byte[] rest(byte[] a, int[] p) {
        byte[] out = Arrays.copyOfRange(a, p[0], a.length);
        p[0] = a.length;
        return out;
    }

    private StreamState refStream(long id, boolean sendRef) throws Fail {
        long cat = id & 3;
        long idx = id >>> 2;
        if (cat == 0) {
            if (idx >= limBidi) throw new Fail("STREAM_LIMIT_ERROR");
            long old = openBidi;
            push(() -> openBidi = old);
            openBidi = Math.max(openBidi, idx + 1);
        } else if (cat == 2) {
            if (sendRef) throw new Fail("STREAM_STATE_ERROR");
            if (idx >= limUni) throw new Fail("STREAM_LIMIT_ERROR");
            long old = openUni;
            push(() -> openUni = old);
            openUni = Math.max(openUni, idx + 1);
        } else if (cat == 1) {
            if (idx >= localBidi) throw new Fail("STREAM_STATE_ERROR");
        } else {
            if (sendRef) {
                if (idx >= localUni) throw new Fail("STREAM_STATE_ERROR");
            } else {
                throw new Fail("STREAM_STATE_ERROR");
            }
        }
        StreamState s = streams.get(id);
        if (s == null) {
            s = new StreamState();
            jput(streams, id, s);
        }
        return s;
    }

    private void insertBytes(TreeMap<Long, byte[]> map, long off, byte[] data, boolean check)
            throws Fail {
        if (data.length == 0) return;
        long end = off + data.length;
        Map.Entry<Long, byte[]> floor = map.floorEntry(off);
        long lo = off;
        if (floor != null && floor.getKey() + floor.getValue().length >= off) lo = floor.getKey();
        SortedMap<Long, byte[]> window = map.subMap(lo, true, end, true);
        List<Map.Entry<Long, byte[]>> affected = new ArrayList<>();
        for (Map.Entry<Long, byte[]> e : window.entrySet()) {
            long s = e.getKey();
            long t = s + e.getValue().length;
            if (t >= off && s <= end) affected.add(e);
        }
        if (check) {
            for (Map.Entry<Long, byte[]> e : affected) {
                long s = e.getKey();
                long t = s + e.getValue().length;
                byte[] old = e.getValue();
                long a = Math.max(s, off);
                long b = Math.min(t, end);
                for (long i = a; i < b; i++) {
                    if (old[(int) (i - s)] != data[(int) (i - off)]) throw new Fail(PV);
                }
            }
        }
        long ns = off;
        long ne = end;
        for (Map.Entry<Long, byte[]> e : affected) {
            long s = e.getKey();
            long t = s + e.getValue().length;
            if (s < ns) ns = s;
            if (t > ne) ne = t;
        }
        byte[] merged = new byte[(int) (ne - ns)];
        for (Map.Entry<Long, byte[]> e : affected) {
            byte[] old = e.getValue();
            System.arraycopy(old, 0, merged, (int) (e.getKey() - ns), old.length);
        }
        System.arraycopy(data, 0, merged, (int) (off - ns), data.length);
        for (Map.Entry<Long, byte[]> e : affected) jremove(map, e.getKey());
        jput(map, ns, merged);
    }

    private void ivAdd(TreeMap<Long, Long> map, long lo, long hi) {
        if (hi <= lo) return;
        Map.Entry<Long, Long> floor = map.floorEntry(lo);
        long start = lo;
        if (floor != null && floor.getValue() >= lo) start = floor.getKey();
        SortedMap<Long, Long> window = map.subMap(start, true, hi, true);
        List<Long> keys2 = new ArrayList<>();
        long ns = lo;
        long ne = hi;
        for (Map.Entry<Long, Long> e : window.entrySet()) {
            if (e.getValue() >= lo && e.getKey() <= hi) {
                keys2.add(e.getKey());
                if (e.getKey() < ns) ns = e.getKey();
                if (e.getValue() > ne) ne = e.getValue();
            }
        }
        for (Long k : keys2) jremove(map, k);
        jput(map, ns, ne);
    }

    private boolean decodeFrame(byte[] pl, int[] p, int level, long destSeq, Out o) throws Fail {
        long t = readType(pl, p);
        if (t > 0x31) throw new Fail(FE);
        switch ((int) t) {
            case 0x00:
                o.u8(0x00);
                return false;
            case 0x01:
                o.u8(0x01);
                return false;
            case 0x02:
            case 0x03:
                {
                    long la = varint(pl, p);
                    long delay = varint(pl, p);
                    long count = varint(pl, p);
                    long first = varint(pl, p);
                    if (first > la) throw new Fail(FE);
                    List<long[]> ranges = new ArrayList<>();
                    List<long[]> pairs = new ArrayList<>();
                    long low = la - first;
                    ranges.add(new long[] {low, la});
                    for (long i = 0; i < count; i++) {
                        long gap = varint(pl, p);
                        long range = varint(pl, p);
                        pairs.add(new long[] {gap, range});
                        if (low < gap + 2) throw new Fail(FE);
                        long high = low - gap - 2;
                        if (range > high) throw new Fail(FE);
                        ranges.add(new long[] {high - range, high});
                        low = high - range;
                    }
                    long e0 = 0;
                    long e1 = 0;
                    long ce = 0;
                    if (t == 3) {
                        e0 = varint(pl, p);
                        e1 = varint(pl, p);
                        ce = varint(pl, p);
                    }
                    AckState a = acks.get(level);
                    for (long[] r : ranges) ivAdd(a.iv, r[0], r[1] + 1);
                    long oe0 = a.e0;
                    long oe1 = a.e1;
                    long oce = a.ce;
                    a.e0 = Math.max(a.e0, e0);
                    a.e1 = Math.max(a.e1, e1);
                    a.ce = Math.max(a.ce, ce);
                    push(() -> {
                        a.e0 = oe0;
                        a.e1 = oe1;
                        a.ce = oce;
                    });
                    o.u8((int) t);
                    o.v(la);
                    o.v(delay);
                    o.v(count);
                    o.v(first);
                    for (long[] pr : pairs) {
                        o.v(pr[0]);
                        o.v(pr[1]);
                    }
                    if (t == 3) {
                        o.v(e0);
                        o.v(e1);
                        o.v(ce);
                    }
                    return false;
                }
            case 0x04:
                {
                    if (level != 2) throw new Fail(PV);
                    long id = varint(pl, p);
                    long err = varint(pl, p);
                    long fin = varint(pl, p);
                    StreamState s = refStream(id, false);
                    if (fin < s.high) throw new Fail("FINAL_SIZE_ERROR");
                    if (s.finalSize != null && s.finalSize != fin) throw new Fail("FINAL_SIZE_ERROR");
                    long cand = Math.max(s.high, fin);
                    if (cand > limStream) throw new Fail("FLOW_CONTROL_ERROR");
                    long newUsed = used - s.high + cand;
                    if (newUsed > limConn) throw new Fail("FLOW_CONTROL_ERROR");
                    if (s.finalSize == null) {
                        Long old = s.finalSize;
                        push(() -> s.finalSize = old);
                        s.finalSize = fin;
                    }
                    if (s.reset == null) {
                        Long old = s.reset;
                        push(() -> s.reset = old);
                        s.reset = err;
                    }
                    long oldHigh = s.high;
                    push(() -> s.high = oldHigh);
                    s.high = cand;
                    long oldUsed = used;
                    push(() -> used = oldUsed);
                    used = newUsed;
                    o.u8(0x04);
                    o.v(id);
                    o.v(err);
                    o.v(fin);
                    return false;
                }
            case 0x05:
                {
                    if (level != 2) throw new Fail(PV);
                    long id = varint(pl, p);
                    long err = varint(pl, p);
                    StreamState s = refStream(id, true);
                    if (s.stop == null) {
                        Long old = s.stop;
                        push(() -> s.stop = old);
                        s.stop = err;
                    }
                    o.u8(0x05);
                    o.v(id);
                    o.v(err);
                    return false;
                }
            case 0x06:
                {
                    long off = varint(pl, p);
                    long len = varint(pl, p);
                    if (off + len > MAXP) throw new Fail(FE);
                    byte[] data = take(pl, p, len);
                    insertBytes(crypto.get(level), off, data, true);
                    o.u8(0x06);
                    o.v(off);
                    o.v(len);
                    o.raw(data);
                    return false;
                }
            case 0x07:
                throw new Fail(PV);
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f:
                {
                    if (level != 2) throw new Fail(PV);
                    boolean offFlag = (t & 4) != 0;
                    boolean lenFlag = (t & 2) != 0;
                    boolean finFlag = (t & 1) != 0;
                    long id = varint(pl, p);
                    long off = offFlag ? varint(pl, p) : 0;
                    byte[] data;
                    if (lenFlag) {
                        long len = varint(pl, p);
                        data = take(pl, p, len);
                    } else {
                        data = rest(pl, p);
                    }
                    long end = off + data.length;
                    if (end > MAXP) throw new Fail(FE);
                    StreamState s = refStream(id, false);
                    if (s.finalSize != null) {
                        if (end > s.finalSize) throw new Fail("FINAL_SIZE_ERROR");
                        if (finFlag && end != s.finalSize) throw new Fail("FINAL_SIZE_ERROR");
                    } else if (finFlag) {
                        if (end < s.high) throw new Fail("FINAL_SIZE_ERROR");
                        Long old = s.finalSize;
                        push(() -> s.finalSize = old);
                        s.finalSize = end;
                    }
                    long cand = Math.max(s.high, end);
                    if (cand > limStream) throw new Fail("FLOW_CONTROL_ERROR");
                    long newUsed = used - s.high + cand;
                    if (newUsed > limConn) throw new Fail("FLOW_CONTROL_ERROR");
                    if (data.length > 0 && s.reset == null) {
                        insertBytes(s.chunks, off, data, true);
                    }
                    long oldHigh = s.high;
                    push(() -> s.high = oldHigh);
                    s.high = cand;
                    long oldUsed = used;
                    push(() -> used = oldUsed);
                    used = newUsed;
                    o.u8((int) t);
                    o.v(id);
                    if (offFlag) o.v(off);
                    if (lenFlag) o.v(data.length);
                    o.raw(data);
                    return false;
                }
            case 0x10:
                {
                    if (level != 2) throw new Fail(PV);
                    long v = varint(pl, p);
                    long old = sendMaxData;
                    push(() -> sendMaxData = old);
                    sendMaxData = Math.max(old, v);
                    o.u8(0x10);
                    o.v(v);
                    return false;
                }
            case 0x11:
                {
                    if (level != 2) throw new Fail(PV);
                    long id = varint(pl, p);
                    long v = varint(pl, p);
                    StreamState s = refStream(id, true);
                    long old = s.sendMax;
                    push(() -> s.sendMax = old);
                    s.sendMax = Math.max(old, v);
                    o.u8(0x11);
                    o.v(id);
                    o.v(v);
                    return false;
                }
            case 0x12:
            case 0x13:
                {
                    if (level != 2) throw new Fail(PV);
                    long v = varint(pl, p);
                    if (v > MAXSTREAMS) throw new Fail(FE);
                    if (t == 0x12) {
                        long old = sendMaxStreamsBidi;
                        push(() -> sendMaxStreamsBidi = old);
                        sendMaxStreamsBidi = Math.max(old, v);
                    } else {
                        long old = sendMaxStreamsUni;
                        push(() -> sendMaxStreamsUni = old);
                        sendMaxStreamsUni = Math.max(old, v);
                    }
                    o.u8((int) t);
                    o.v(v);
                    return false;
                }
            case 0x14:
                {
                    if (level != 2) throw new Fail(PV);
                    long v = varint(pl, p);
                    o.u8(0x14);
                    o.v(v);
                    return false;
                }
            case 0x15:
                {
                    if (level != 2) throw new Fail(PV);
                    long id = varint(pl, p);
                    long v = varint(pl, p);
                    refStream(id, false);
                    o.u8(0x15);
                    o.v(id);
                    o.v(v);
                    return false;
                }
            case 0x16:
            case 0x17:
                {
                    if (level != 2) throw new Fail(PV);
                    long v = varint(pl, p);
                    if (v > MAXSTREAMS) throw new Fail(FE);
                    o.u8((int) t);
                    o.v(v);
                    return false;
                }
            case 0x18:
                {
                    if (level != 2) throw new Fail(PV);
                    long seq = varint(pl, p);
                    long rpt = varint(pl, p);
                    int cidLen = u8(pl, p);
                    if (cidLen < 1 || cidLen > 20) throw new Fail(FE);
                    if (rpt > seq) throw new Fail(FE);
                    byte[] cid = take(pl, p, cidLen);
                    byte[] token = take(pl, p, 16);
                    CidRec prev = peerObserved.get(seq);
                    if (prev != null) {
                        if (!Arrays.equals(prev.cid, cid) || !Arrays.equals(prev.token, token)) {
                            throw new Fail(PV);
                        }
                    }
                    String cidKey = hex(cid);
                    Long owner = cidOwner.get(cidKey);
                    if (owner != null && owner.longValue() != seq) throw new Fail(PV);
                    if (prev == null) {
                        jput(peerObserved, seq, new CidRec(cid, token));
                        jput(cidOwner, cidKey, seq);
                    }
                    long oldThreshold = retirePriorTo;
                    push(() -> retirePriorTo = oldThreshold);
                    retirePriorTo = Math.max(retirePriorTo, rpt);
                    List<Long> toRemove = new ArrayList<>();
                    for (Long s : peerActive.headSet(retirePriorTo)) toRemove.add(s);
                    for (Long s : toRemove) jdel(peerActive, s);
                    if (seq >= retirePriorTo) jadd(peerActive, seq);
                    if (peerActive.size() > limCids) throw new Fail("CONNECTION_ID_LIMIT_ERROR");
                    o.u8(0x18);
                    o.v(seq);
                    o.v(rpt);
                    o.u8(cidLen);
                    o.raw(cid);
                    o.raw(token);
                    return false;
                }
            case 0x19:
                {
                    if (level != 2) throw new Fail(PV);
                    long seq = varint(pl, p);
                    if (seq >= localCids.size() || seq == destSeq) throw new Fail(PV);
                    jadd(retiredLocal, seq);
                    o.u8(0x19);
                    o.v(seq);
                    return false;
                }
            case 0x1a:
            case 0x1b:
                {
                    if (level != 2) throw new Fail(PV);
                    byte[] data = take(pl, p, 8);
                    o.u8((int) t);
                    o.raw(data);
                    return false;
                }
            case 0x1c:
                {
                    long err = varint(pl, p);
                    long trigger = varint(pl, p);
                    long rlen = varint(pl, p);
                    byte[] reason = take(pl, p, rlen);
                    o.u8(0x1c);
                    o.v(err);
                    o.v(trigger);
                    o.v(rlen);
                    o.raw(reason);
                    return true;
                }
            case 0x1d:
                {
                    if (level != 2) throw new Fail(PV);
                    long err = varint(pl, p);
                    long rlen = varint(pl, p);
                    byte[] reason = take(pl, p, rlen);
                    o.u8(0x1d);
                    o.v(err);
                    o.v(rlen);
                    o.raw(reason);
                    return true;
                }
            case 0x1e:
                throw new Fail(PV);
            case 0x30:
                {
                    if (level != 2) throw new Fail(PV);
                    byte[] data = rest(pl, p);
                    o.u8(0x30);
                    o.raw(data);
                    return false;
                }
            case 0x31:
                {
                    if (level != 2) throw new Fail(PV);
                    long len = varint(pl, p);
                    byte[] data = take(pl, p, len);
                    o.u8(0x31);
                    o.v(len);
                    o.raw(data);
                    return false;
                }
            default:
                throw new Fail(FE);
        }
    }

    // ------------------------------------------------------------------ output
    private Map<String, Object> result() {
        List<Object> keyRows = new ArrayList<>();
        if (keys[0]) keyRows.add("I");
        if (keys[1]) keyRows.add("H");
        if (keys[2]) keyRows.add("A");

        List<Object> epochRows = new ArrayList<>();
        for (Map.Entry<Long, EpochRec> e : epochs.entrySet()) {
            epochRows.add(
                    Main.object(
                            "epoch",
                            e.getKey(),
                            "min",
                            e.getValue().min,
                            "max",
                            e.getValue().max,
                            "count",
                            e.getValue().count));
        }

        List<Object> streamRows = new ArrayList<>();
        for (Map.Entry<Long, StreamState> e : streams.entrySet()) {
            StreamState s = e.getValue();
            List<Object> ranges = new ArrayList<>();
            long unique = 0;
            long prefix = 0;
            MessageDigest md = digest();
            boolean first = true;
            for (Map.Entry<Long, byte[]> c : s.chunks.entrySet()) {
                long st = c.getKey();
                long en = st + c.getValue().length;
                List<Object> pair = new ArrayList<>();
                pair.add(st);
                pair.add(en);
                ranges.add(pair);
                unique += c.getValue().length;
                if (first) {
                    first = false;
                    if (st == 0) {
                        prefix = c.getValue().length;
                        md.update(c.getValue());
                    }
                }
            }
            streamRows.add(
                    Main.object(
                            "id",
                            e.getKey(),
                            "high",
                            s.high,
                            "final",
                            s.fin,
                            "reset",
                            s.reset,
                            "stop",
                            s.stop,
                            "send_max",
                            s.sendMax,
                            "ranges",
                            ranges,
                            "unique",
                            unique,
                            "prefix",
                            prefix,
                            "sha256",
                            hex(md.digest())));
        }

        List<Object> cryptoRows = new ArrayList<>();
        for (int lvl = 0; lvl < 3; lvl++) {
            TreeMap<Long, byte[]> map = crypto.get(lvl);
            List<Object> ranges = new ArrayList<>();
            long unique = 0;
            long prefix = 0;
            MessageDigest md = digest();
            boolean first = true;
            for (Map.Entry<Long, byte[]> c : map.entrySet()) {
                long st = c.getKey();
                long en = st + c.getValue().length;
                List<Object> pair = new ArrayList<>();
                pair.add(st);
                pair.add(en);
                ranges.add(pair);
                unique += c.getValue().length;
                if (first) {
                    first = false;
                    if (st == 0) {
                        prefix = c.getValue().length;
                        md.update(c.getValue());
                    }
                }
            }
            cryptoRows.add(
                    Main.object(
                            "level",
                            levelName(lvl),
                            "ranges",
