                if finFlag and end != s['fin']: raise Fail('FINAL_SIZE_ERROR')
            elif finFlag:
                if end < s['high']: raise Fail('FINAL_SIZE_ERROR')
                s['fin'] = end
            cand = max(s['high'], end)
            if cand > self.limStream: raise Fail('FLOW_CONTROL_ERROR')
            if self.used - s['high'] + cand > self.limConn: raise Fail('FLOW_CONTROL_ERROR')
            if data and s['reset'] is None:
                self.insert_bytes(s['data'], off, data, True)
            self.used += cand - s['high']
            s['high'] = cand
            out = venc(t) + venc(idv)
            if offFlag: out += venc(off)
            if lenFlag: out += venc(len(data))
            out += data
            canon.append(out)
            return False
        if t == 0x10:
            need_a()
            v = vdec(pl, pos)
            self.sendMaxData = max(self.sendMaxData, v)
            canon.append(venc(0x10) + venc(v))
            return False
        if t == 0x11:
            need_a()
            idv = vdec(pl, pos); v = vdec(pl, pos)
            s = self.ref_stream(idv, True)
            s['send_max'] = max(s['send_max'], v)
            canon.append(venc(0x11) + venc(idv) + venc(v))
            return False
        if t in (0x12, 0x13):
            need_a()
            v = vdec(pl, pos)
            if v > MAXST: raise Fail(FE)
            if t == 0x12: self.smsBidi = max(self.smsBidi, v)
            else: self.smsUni = max(self.smsUni, v)
            canon.append(venc(t) + venc(v))
            return False
        if t == 0x14:
            need_a()
            v = vdec(pl, pos)
            canon.append(venc(0x14) + venc(v))
            return False
        if t == 0x15:
            need_a()
            idv = vdec(pl, pos); v = vdec(pl, pos)
            self.ref_stream(idv, False)
            canon.append(venc(0x15) + venc(idv) + venc(v))
            return False
        if t in (0x16, 0x17):
            need_a()
            v = vdec(pl, pos)
            if v > MAXST: raise Fail(FE)
            canon.append(venc(t) + venc(v))
            return False
        if t == 0x18:
            need_a()
            seq = vdec(pl, pos); rpt = vdec(pl, pos)
            cidLen = take(pl, pos, 1)[0]
            if not (1 <= cidLen <= 20): raise Fail(FE)
            if rpt > seq: raise Fail(FE)
            cid = take(pl, pos, cidLen); token = take(pl, pos, 16)
            if seq in self.peerObs:
                pc, pt = self.peerObs[seq]
                if pc != cid or pt != token: raise Fail('PROTOCOL_VIOLATION')
            owner = self.peerOwner.get(cid)
            if owner is not None and owner != seq: raise Fail('PROTOCOL_VIOLATION')
            if seq not in self.peerObs:
                self.peerObs[seq] = (cid, token)
                self.peerOwner[cid] = seq
            self.threshold = max(self.threshold, rpt)
            self.peerActive = {s for s in self.peerActive if s >= self.threshold}
            if seq >= self.threshold:
                self.peerActive.add(seq)
            if len(self.peerActive) > self.limCids: raise Fail('CONNECTION_ID_LIMIT_ERROR')
            canon.append(venc(0x18) + venc(seq) + venc(rpt) + bytes([cidLen]) + cid + token)
            return False
        if t == 0x19:
            need_a()
            seq = vdec(pl, pos)
            if seq >= len(self.localCids) or seq == destSeq: raise Fail('PROTOCOL_VIOLATION')
            self.retiredLocal.add(seq)
            canon.append(venc(0x19) + venc(seq))
            return False
        if t in (0x1a, 0x1b):
            need_a()
            d = take(pl, pos, 8)
            canon.append(venc(t) + d)
            return False
        if t == 0x1c:
            err = vdec(pl, pos); trg = vdec(pl, pos); rl = vdec(pl, pos)
            r = take(pl, pos, rl)
            canon.append(venc(0x1c) + venc(err) + venc(trg) + venc(rl) + r)
            return True
        if t == 0x1d:
            need_a()
            err = vdec(pl, pos); rl = vdec(pl, pos)
            r = take(pl, pos, rl)
            canon.append(venc(0x1d) + venc(err) + venc(rl) + r)
            return True
        if t == 0x1e:
            raise Fail('PROTOCOL_VIOLATION')
        if t == 0x30:
            need_a()
            d = bytes(pl[pos[0]:]); pos[0] = len(pl)
            canon.append(venc(0x30) + d)
            return False
        if t == 0x31:
            need_a()
            ln = vdec(pl, pos); d = take(pl, pos, ln)
            canon.append(venc(0x31) + venc(ln) + d)
            return False
        raise Fail(FE)

    # ---------- output ----------
    def result(self):
        streams = []
        for idv in sorted(self.streams):
            s = self.streams[idv]
            rr, uniq, pref, h = ranges_of(s['data'])
            streams.append(dict(id=idv, high=s['high'], final=s['fin'], reset=s['reset'],
                                stop=s['stop'], send_max=s['send_max'],
                                ranges=[list(x) for x in rr], unique=uniq, prefix=pref, sha256=h))
        crypto = []
        for lv in ('I','H','A'):
            rr, uniq, pref, h = ranges_of(self.crypto[lv])
            crypto.append(dict(level=lv, ranges=[list(x) for x in rr], unique=uniq,
                               prefix=pref, sha256=h))
        acked = []
        for lv in ('I','H','A'):
            ivs = iv_merge(self.ack[lv])
            count = sum(e-s for s,e in ivs)
            hb = b''
            prefix = 0
            if ivs and ivs[0][0] == 0: prefix = ivs[0][1]
            for s, e in ivs:
                hb += s.to_bytes(8,'big') + e.to_bytes(8,'big')
            acked.append(dict(level=lv, count=count, intervals=len(ivs), prefix=prefix,
                              sha256=sha(hb), ecn=list(self.ecn[lv])))
        peer = [dict(sequence=s, id=self.peerObs[s][0].hex(), token=self.peerObs[s][1].hex())
                for s in sorted(self.peerActive)]
        retired = []
        rl = sorted(self.retiredLocal)
        i = 0
        while i < len(rl):
            j = i
            while j+1 < len(rl) and rl[j+1] == rl[j]+1: j += 1
            retired.append([rl[i], rl[j]+1])
            i = j+1
        epochs = [dict(epoch=g, min=v[0], max=v[1], count=v[2]) for g, v in sorted(self.epochs.items())]
        return dict(
            packets=self.outPackets,
            datagrams=self.outDatagrams,
            closed=self.closeInfo,
            keys=[k for k in ('I','H','A') if k in self.keys],
            received=dict(I=self.largest['I'], H=self.largest['H'], A=self.largest['A']),
            key_epoch=self.currentEpoch,
            epochs=epochs,
            opened=dict(bidi=self.openBidi, uni=self.openUni),
            used=self.used,
            send_max_data=self.sendMaxData,
            send_max_streams=dict(bidi=self.smsBidi, uni=self.smsUni),
            streams=streams,
            crypto=crypto,
            acknowledged=acked,
            peer_cids=peer,
            retire_prior_to=self.threshold,
            retired_local=retired)

def audit(t):
    r = Ref(t)
    r.run(t['events'])
    return r.result()
